const config = $loop.alertConfig;
const history = $steps['fetch-latest-history'].response.data || [];
if (history.length === 0) return null;

const todayRecord = history[0];
const yesterdayRecord = history[1] || todayRecord;
let triggered = false;
let alertType = 'INFO';
let severity = 'WARNING';
let message = '';

// 1. Low Occupancy Check
if (todayRecord.occupancy_pct < 30.0) {
  triggered = true;
  alertType = 'LOW_OCCUPANCY';
  severity = 'WARNING';
  message = `Baja ocupación crítica: ${todayRecord.occupancy_pct}% (umbral: 30%)`;
}
// 2. High Demand Opportunity Check
else if (todayRecord.occupancy_pct > 95.0) {
  triggered = true;
  alertType = 'HIGH_DEMAND_OPPORTUNITY';
  severity = 'INFO';
  message = `Alta demanda detectada: Ocupación al ${todayRecord.occupancy_pct}%. Considera elevar tarifas.`;
}
// 3. Price Variance Check (> 20% vs ayer)
else {
  const variancePct = Math.abs((todayRecord.applied_rate - yesterdayRecord.applied_rate) / yesterdayRecord.applied_rate) * 100;
  if (variancePct > 20.0) {
    triggered = true;
    alertType = 'HIGH_PRICE_VARIANCE';
    severity = 'CRITICAL';
    message = `Variación de precio elevada: ${variancePct.toFixed(1)}% vs tarifa anterior`;
  }
}

if (!triggered) return null;

return {
  hotel_id: config.hotel_id,
  alert_id: config.alert_id,
  alert_type: alertType,
  severity: severity,
  message: message,
  target_date: todayRecord.target_date,
  current_rate: todayRecord.applied_rate,
  created_at: new Date().toISOString()
};
